const payloads = [
  { method: 'POST', body: `content=${encodeURIComponent(html)}` },
  { method: 'POST', body: `data=${encodeURIComponent(html)}` },
  { method: 'POST', body: `html=${encodeURIComponent(html)}` },
  { method: 'POST', body: `page=${encodeURIComponent(html)}` },
